 42→		HookNameSessionStart,
 43→		HookNameSessionEnd,
 44→		HookNameStop,
 45→		HookNameUserPromptSubmit,
 46→		HookNamePreTask,
 47→		HookNamePostTask,
 48→		HookNamePostTodo,
 49→	}
