681→		commit, err := s.repo.CommitObject(ref.Hash())
682→		if err != nil {
683→			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit object: %w", err)
684→		}
685→		return ref.Hash(), commit.TreeHash, nil
686→	}
687→
688→	// Branch doesn't exist, use current HEAD's tree as base
689→	head, err := s.repo.Head()
690→	if err != nil {
691→		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get HEAD: %w", err)
692→	}
693→
694→	headCommit, err := s.repo.CommitObject(head.Hash())
695→	if err != nil {
696→		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get HEAD commit: %w", err)
697→	}
698→
699→	return plumbing.ZeroHash, headCommit.TreeHash, nil
