 32→// InitRepo initializes a git repository in the given directory with test user config.
 33→func InitRepo(t *testing.T, repoDir string) {
 34→	t.Helper()
 35→
 36→	repo, err := git.PlainInit(repoDir, false)
 37→	if err != nil {
 38→		t.Fatalf("failed to init git repo: %v", err)
 39→	}
 40→
 41→	// Configure git user for commits
 42→	cfg, err := repo.Config()
 43→	if err != nil {
 44→		t.Fatalf("failed to get repo config: %v", err)
 45→	}
 46→	cfg.User.Name = "Test User"
 47→	cfg.User.Email = "test@example.com"
 48→
 49→	// Disable GPG signing for test commits
 50→	if cfg.Raw == nil {
 51→		cfg.Raw = config.New()
 52→	}
 53→	cfg.Raw.Section("commit").SetOption("gpgsign", "false")
 54→
 55→	if err := repo.SetConfig(cfg); err != nil {
 56→		t.Fatalf("failed to set repo config: %v", err)
 57→	}
 58→}
