 60→// WriteFile creates a file with the given content in the repo directory.
 61→// It creates parent directories as needed.
 62→func WriteFile(t *testing.T, repoDir, path, content string) {
 63→	t.Helper()
 64→
 65→	fullPath := filepath.Join(repoDir, path)
 66→
 67→	// Create parent directories
 68→	dir := filepath.Dir(fullPath)
 69→	//nolint:gosec // test code, permissions are intentionally standard
 70→	if err := os.MkdirAll(dir, 0o755); err != nil {
 71→		t.Fatalf("failed to create directory %s: %v", dir, err)
 72→	}
 73→
 74→	//nolint:gosec // test code, permissions are intentionally standard
 75→	if err := os.WriteFile(fullPath, []byte(content), 0o644); err != nil {
 76→		t.Fatalf("failed to write file %s: %v", path, err)
 77→	}
 78→}
