113→// GitAdd stages files for commit.
114→func GitAdd(t *testing.T, repoDir string, paths ...string) {
115→	t.Helper()
116→
117→	repo, err := git.PlainOpen(repoDir)
118→	if err != nil {
119→		t.Fatalf("failed to open git repo: %v", err)
120→	}
121→
122→	worktree, err := repo.Worktree()
123→	if err != nil {
