		}
		t.Cleanup(func() {
			removeWorktree(tmpDir, worktreeDir)
		})

		t.Chdir(worktreeDir)

		root, err := GetMainRepoRoot(context.Background())
		if err != nil {
			t.Fatalf("GetMainRepoRoot(context.Background()) failed: %v", err)
		}

		if root != tmpDir {
			t.Errorf("GetMainRepoRoot(context.Background()) = %q, want %q", root, tmpDir)
		}
	})
}

