// TestGetSessionDir_ClaudeWorktree verifies that GetSessionDir returns the
// correct project directory when running from a Claude Code worktree
// (created under .claude/worktrees/).
//
// When Claude Code uses --worktree, it creates a git worktree under
// .claude/worktrees/<branch>/. Entire's hooks run from within that worktree,
// so paths.WorktreeRoot() returns the worktree path (e.g.,
// /repo/.claude/worktrees/feature-branch) instead of the main repo path (/repo).
//
// GetSessionDir must use the main repo root (via paths.MainRepoRoot) so the
// sanitized path matches Claude's actual project directory.
func TestGetSessionDir_ClaudeWorktree(t *testing.T) {
	// Cannot use t.Parallel: uses t.Setenv and t.Chdir
	// Set up a git repo with an initial commit
	mainRepo := t.TempDir()
	testutil.InitRepo(t, mainRepo)
	testutil.WriteFile(t, mainRepo, "README.md", "# Test")
	testutil.GitAdd(t, mainRepo, "README.md")
	testutil.GitCommit(t, mainRepo, "initial commit")

	// Resolve symlinks for reliable path comparison
	mainRepo, err := filepath.EvalSymlinks(mainRepo)
	if err != nil {
		t.Fatalf("EvalSymlinks: %v", err)
	}

	// Create a Claude worktree under .claude/worktrees/ (mimicking Claude Code --worktree)
	worktreeBranch := "feature-branch"
	worktreeDir := filepath.Join(mainRepo, ".claude", "worktrees", worktreeBranch)
	if err := os.MkdirAll(filepath.Dir(worktreeDir), 0o755); err != nil {
		t.Fatalf("failed to create .claude/worktrees dir: %v", err)
	}

	cmd := exec.Command("git", "worktree", "add", worktreeDir, "-b", worktreeBranch) //nolint:noctx // test code
	cmd.Dir = mainRepo
	cmd.Env = testutil.GitIsolatedEnv()
	if output, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("failed to create worktree: %v\nOutput: %s", err, output)
	}

	// Override home dir to make GetSessionDir deterministic
	fakeHome := t.TempDir()
	t.Setenv("HOME", fakeHome)
	t.Setenv("ENTIRE_TEST_CLAUDE_PROJECT_DIR", "") // Ensure no test override

	ag := &ClaudeCodeAgent{}

	// GetSessionDir from main repo path (what Claude uses for its project dir)
	mainSessionDir, err := ag.GetSessionDir(mainRepo)
	if err != nil {
		t.Fatalf("GetSessionDir(mainRepo) error: %v", err)
	}

	// GetSessionDir from worktree path (what a naive WorktreeRoot call would produce)
	worktreeSessionDir, err := ag.GetSessionDir(worktreeDir)
	if err != nil {
		t.Fatalf("GetSessionDir(worktreeDir) error: %v", err)
	}

	// These MUST differ: the worktree path includes .claude/worktrees/<branch>
	if mainSessionDir == worktreeSessionDir {
		t.Fatal("precondition: main and worktree session dirs should differ when using raw paths")
	}

	// But MainRepoRoot should resolve back to the main repo even from the worktree
	paths.ClearWorktreeRootCache()
	t.Chdir(worktreeDir)

	mainRoot, err := paths.MainRepoRoot(context.Background())
	if err != nil {
		t.Fatalf("MainRepoRoot error: %v", err)
	}

	if mainRoot != mainRepo {
		t.Errorf("MainRepoRoot() = %q, want %q", mainRoot, mainRepo)
	}

	resolvedSessionDir, err := ag.GetSessionDir(mainRoot)
	if err != nil {
		t.Fatalf("GetSessionDir(mainRoot) error: %v", err)
	}

	if resolvedSessionDir != mainSessionDir {
		t.Errorf("GetSessionDir via MainRepoRoot mismatch:\n"+
			"  expected: %s\n"+
			"  got:      %s",
			mainSessionDir, resolvedSessionDir)
	}
}

