func TestMainRepoRoot_MainRepo(t *testing.T) {
	// Cannot use t.Parallel: uses t.Chdir
	tmpDir := t.TempDir()
	resolved, err := filepath.EvalSymlinks(tmpDir)
	if err != nil {
		t.Fatalf("EvalSymlinks: %v", err)
	}
