	// Create linked worktree
	worktreeDir := filepath.Join(tmpDir, ".claude", "worktrees", "test-branch")
	if err := os.MkdirAll(filepath.Dir(worktreeDir), 0o755); err != nil {
		t.Fatalf("MkdirAll: %v", err)
	}
